function Certify(cards, B):
    k <- len(cards) - 1
    for i = 0..k-1:
        if cards[i] > B * cards[i+1]: return Invalid
    mult_bound <- B^k * cards[k]
    assert cards[0] <= mult_bound
    lb <- log_B(cards[0] / cards[k])
    assert k >= lb
    return Certificate(k, B, lb, mult_bound)

Complexity: O(k) time, O(1) space
